import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:flutter_test/flutter_test.dart';
import 'package:d_0_pension/core/engine/formula_evaluator.dart';
import 'package:d_0_pension/core/models/pension_calculation.dart';

/// Cross-validation test: App (FormulaEvaluator) vs REAL Excel calculations
///
/// This test reads the JSON output generated by excel_real_scenarios_v5.py
/// which used the REAL Excel file (Calculadora_UNPROTECTED.xlsm) as the
/// calculation engine. The Python script:
///   1. Copied the Excel file for each scenario
///   2. Wrote input values to DATOS GEN. sheet cells (E4-E12)
///   3. Let Excel calculate ALL formulas
///   4. Read back the calculated results from all sheets
///
/// This test then feeds the SAME inputs to the Flutter FormulaEvaluator
/// and compares the results. They MUST be identical (within tolerance).
///
/// IMPORTANT: The Excel file has hardcoded salary history data in
/// SAL. PROM MOD 40 sheet (rows 22-75). This data is NOT derived from
/// input cells. Therefore, the Excel-computed salario_promedio, uma_diaria,
/// salario_minimo, and salario_prom_final are used as inputs to the
/// FormulaEvaluator (since the app doesn't have access to the raw salary
/// history).
///
/// Run with: flutter test test/validate_excel_real_scenarios_test.dart
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late FormulaEvaluator evaluator;
  late Map<String, dynamic> excelScenarios;

  setUpAll(() async {
    // Load Excel-generated reference output
    final file = File('excel_real_scenarios_output.json');
    final jsonStr = await file.readAsString();
    excelScenarios = json.decode(jsonStr) as Map<String, dynamic>;
    final scenarios = excelScenarios['scenarios'] as Map<String, dynamic>;
    expect(scenarios.length, 9, reason: 'Expected 9 scenarios from Excel');

    evaluator = FormulaEvaluator();
    await evaluator.initialize();
  });

  /// Round edad retiro using threshold 0.5 (matching Excel formula)
  /// 60.5 -> 61, 60.49 -> 60, 61.0 -> 61, 61.5 -> 62
  int _roundEdadRetiro(double edad) {
    final decimal = edad - edad.floor();
    if (decimal < 0.5) {
      return edad.floor();
    } else {
      return edad.ceil();
    }
  }

  /// Helper: approxEqual with tolerance 0.02 absolute OR 0.1% relative
  bool approxEqual(double a, double b, {double absTol = 0.02, double relTol = 0.001}) {
    if (a == b) return true;
    final diff = (a - b).abs();
    if (diff <= absTol) return true;
    if (a.abs() > relTol && b.abs() > relTol) {
      return diff / math.max(a.abs(), b.abs()) <= relTol;
    }
    return false;
  }

  /// Parse a string value that may contain commas or be a number
  double _parseDouble(dynamic val) {
    if (val == null) return double.nan;
    if (val is num) return val.toDouble();
    if (val is String) {
      final cleaned = val.replaceAll(',', '').trim();
      if (cleaned.isEmpty) return double.nan;
      final parsed = double.tryParse(cleaned);
      return parsed ?? double.nan;
    }
    return double.nan;
  }

  /// Parse a string value returning null if invalid
  double? _parseDoubleNullable(dynamic val) {
    if (val == null) return null;
    if (val is num) return val.toDouble();
    if (val is String) {
      final cleaned = val.replaceAll(',', '').trim();
      if (cleaned.isEmpty) return null;
      final parsed = double.tryParse(cleaned);
      return parsed;
    }
    return null;
  }

  /// Convert Excel's "SI"/"NO" to bool
  bool _parseSiNo(dynamic val) {
    if (val is bool) return val;
    if (val is String) return val.toUpperCase() == 'SI';
    return false;
  }

  /// Extract key outputs from Excel JSON for comparison
  Map<String, dynamic> _extractExcelOutputs(Map<String, dynamic> scenario) {
    final outputs = scenario['outputs'] as Map<String, dynamic>;
    final result = <String, dynamic>{};

    // PENSION MOD. 40 sheet
    final pensionMod40 = outputs['PENSION MOD. 40'] as Map<String, dynamic>?;
    if (pensionMod40 != null) {
      result['pension_mod40.pension_mensual'] = _parseDoubleNullable(pensionMod40['pension_mensual']);
      result['pension_mod40.pension_anual_final'] = _parseDoubleNullable(pensionMod40['pension_anual']);
      result['pension_mod40.porcentaje_por_edad'] = _parseDoubleNullable(pensionMod40['porcentaje_edad']);
      result['pension_mod40.pension_minima_garantizada'] = _parseDoubleNullable(pensionMod40['pension_minima']);
      result['pension_mod40.edad_entera'] = _parseDoubleNullable(pensionMod40['edad_entera']);
    }

    // FACT. + ASIG. MOD.40 sheet
    // NOTE: Field names match the corrected v5 script cell mappings.
    // See excel_real_scenarios_v5.py OUTPUT_CELLS for exact cell references.
    final factAsig = outputs['FACT. + ASIG. MOD.40'] as Map<String, dynamic>?;
    if (factAsig != null) {
      result['fact_asig.pension_mensual'] = _parseDoubleNullable(factAsig['pension_mensual_neta']);
      // cuantia_total_pension_vejez = C30 = C26+C15 (cuantía total pensión vejez 100%)
      result['fact_asig.cuantia_total_pension_vejez'] = _parseDoubleNullable(factAsig['pension_vejez_100']);
      // total_pension_anual = C72 = C30*D16+C59+B53 = pension_mensual_neta * 12
      final pn = _parseDoubleNullable(factAsig['pension_mensual_neta']);
      result['fact_asig.total_pension_anual'] = pn != null ? pn * 12 : null;
      // cuantia_basica = C4 = salarioDiarioPromedio (the input salary from SAL. PROM MOD 40!E19)
      result['fact_asig.salario_diario_promedio'] = _parseDoubleNullable(factAsig['cuantia_basica']);
      // numero_incrementos_raw = C24 = (semanas_cot_m40-500)/52 (RAW, not rounded)
      result['fact_asig.numero_incrementos_anuales'] = _parseDoubleNullable(factAsig['numero_incrementos_raw']);
      // numero_incrementos_rounded = C25 = rounded per Art. 167 LSS
      result['fact_asig.numero_incrementos_redondeado'] = _parseDoubleNullable(factAsig['numero_incrementos_rounded']);
      // total_incrementos_anuales = C26 = C23*C25*1.11
      result['fact_asig.total_incrementos_anuales'] = _parseDoubleNullable(factAsig['total_incrementos_anuales']);
      // total_cuantia_basica_anual = C15 = C13*365*1.11
      result['fact_asig.total_cuantia_basica_anual'] = _parseDoubleNullable(factAsig['total_cuantia_basica_anual']);
      // porcentaje_cuantia_basica = C12 = VLOOKUP - % cuantía básica
      result['fact_asig.porcentaje_cuantia_basica'] = _parseDoubleNullable(factAsig['porcentaje_cuantia_basica']);
      // porcentaje_incremento = C20 = VLOOKUP - % incremento
      result['fact_asig.porcentaje_incremento'] = _parseDoubleNullable(factAsig['porcentaje_incremento']);
    }

    // COSTO MOD. 40 sheet
    // NOTE: costo_anual = G15 = Inversión Total (before AFORE recovery)
    //       costo_total = G19 = Inversión Neta (after AFORE recovery)
    // The app's inversionTotal corresponds to G15 (costo_anual).
    final costoMod40 = outputs['COSTO MOD. 40'] as Map<String, dynamic>?;
    if (costoMod40 != null) {
      result['costo_mod40.inversion_total'] = _parseDoubleNullable(costoMod40['costo_anual']);
      result['costo_mod40.costo_anual'] = _parseDoubleNullable(costoMod40['costo_anual']);
    }

    // PAGO RETROACTIVO sheet
    // NOTE: Excel FINANCIAMIENTO C3 = =+'PAGO RETROACTIVO'!E11 (costo_total)
    // The PAGO RETROACTIVO uses SAL. PROM MOD 40 B22/C22 dates (2028-02-01 to 2029-07-31)
    // which differ from fecha_calculo/nueva_fecha. We extract these values to use
    // as inputs for FINANCIAMIENTO validation.
    final pagoRetroactivo = outputs['PAGO RETROACTIVO'] as Map<String, dynamic>?;
    if (pagoRetroactivo != null) {
      result['pago_retroactivo.costo_modalidad_40'] = _parseDoubleNullable(pagoRetroactivo['costo_modalidad_40']);
      result['pago_retroactivo.actualizaciones'] = _parseDoubleNullable(pagoRetroactivo['actualizaciones']);
      result['pago_retroactivo.recargos'] = _parseDoubleNullable(pagoRetroactivo['recargos']);
      result['pago_retroactivo.costo_total'] = _parseDoubleNullable(pagoRetroactivo['costo_total']);
      result['pago_retroactivo.recuperacion_afore'] = _parseDoubleNullable(pagoRetroactivo['recuperacion_afore']);
      result['pago_retroactivo.inversion_neta'] = _parseDoubleNullable(pagoRetroactivo['inversion_neta']);
    }

    // INVERSION sheet
    final inversion = outputs['INVERSION'] as Map<String, dynamic>?;
    if (inversion != null) {
      result['inversion.edad_sin_mod40'] = _parseDoubleNullable(inversion['edad_sin_mod40']);
      result['inversion.edad_con_mod40'] = _parseDoubleNullable(inversion['edad_con_mod40']);
      result['inversion.pension_mensual_sin'] = _parseDoubleNullable(inversion['pension_mensual_sin']);
      result['inversion.pension_mensual_con'] = _parseDoubleNullable(inversion['pension_mensual_con']);
      result['inversion.ganancia_total'] = _parseDoubleNullable(inversion['ganancia_total']);
      result['inversion.tasa_rendimiento'] = _parseDoubleNullable(inversion['tasa_rendimiento']);
      result['inversion.veredicto'] = inversion['veredicto'] as String?;
    }

    // FINANCIAMIENTO sheet
    final financiamiento = outputs['FINANCIAMIENTO'] as Map<String, dynamic>?;
    if (financiamiento != null) {
      result['financiamiento.periodos_recuperacion'] = _parseDoubleNullable(financiamiento['periodos_recuperacion']);
      result['financiamiento.pension_inmediata'] = _parseDoubleNullable(financiamiento['pension_inmediata']);
      result['financiamiento.pension_liquidacion'] = _parseDoubleNullable(financiamiento['pension_liquidacion']);
      result['financiamiento.flujo_hasta_80'] = _parseDoubleNullable(financiamiento['flujo_hasta_80']);
    }

    // PENSION ACTUAL sheet (sin Mod40 values)
    // NOTE: Excel cell C22 in PENSIÓN ACTUAL contains the MONTHLY pension (same as
    // INVERSION.pension_mensual_sin). The label 'pension_anual_sin_m40' in the v5
    // script is misleading - it's actually monthly. We multiply by 12 to get annual.
    final pensionActual = outputs['PENSI\u00d3N ACTUAL'] as Map<String, dynamic>?;
    if (pensionActual != null) {
      final pensionMensualSinM40 = _parseDoubleNullable(pensionActual['pension_anual_sin_m40']);
      result['pension_actual.pension_anual_sin_m40'] = pensionMensualSinM40 != null ? pensionMensualSinM40 * 12 : null;
    } else {
      result['pension_actual.pension_anual_sin_m40'] = null;
    }

    return result;
  }

  /// Run the FormulaEvaluator with inputs derived from Excel scenario data
  Map<String, dynamic> _runAppCalculations(Map<String, dynamic> excelScenario) {
    final inputs = excelScenario['inputs'] as Map<String, dynamic>;
    final outputs = excelScenario['outputs'] as Map<String, dynamic>;
    final datosGenMod40 = outputs['DATOS GEN. MOD 40'] as Map<String, dynamic>? ?? {};
    final salPromMod40 = outputs['SAL. PROM MOD 40'] as Map<String, dynamic>? ?? {};

    // Parse dates
    final fechaCalculo = DateTime.parse(inputs['fecha_calculo'] as String);

    // Dependents
    final tieneEsposa = _parseSiNo(inputs['tiene_esposa']);
    final numeroHijos = (inputs['hijos'] as num).toInt();
    final numeroPadres = (inputs['padres'] as num).toInt();

    // Edad retiro from Excel (DATOS GEN. MOD 40)
    final edadRetiro = _parseDouble(datosGenMod40['edad_retiro']);

    // Semanas from Excel
    final semanasCotizadas = _parseDouble(datosGenMod40['semanas_cot_m40']).toInt();

    // Salary data from SAL. PROM MOD 40
    final salarioPromedio = _parseDouble(salPromMod40['salario_promedio']);
    final umaDiaria = _parseDouble(salPromMod40['uma_diaria']);
    final salarioMinimo = _parseDouble(salPromMod40['salario_minimo']);
    final salarioPromFinal = _parseDouble(salPromMod40['salario_prom_final']);

    // Pension year from Excel (year of nueva_fecha)
    final nuevaFechaStr = datosGenMod40['nueva_fecha'] as String?;
    final pensionYear = nuevaFechaStr != null
        ? DateTime.parse(nuevaFechaStr).year
        : fechaCalculo.year + 3;

    // 1. FACT + ASIG (CON Mod40)
    final factAsig = evaluator.calculateFactAsig(
      salarioDiarioPromedio: salarioPromFinal,
      umaDiaria: umaDiaria,
      salarioMinimoDiario: salarioMinimo,
      pensionYear: pensionYear,
      semanasCotizadas: semanasCotizadas,
      tieneEsposa: tieneEsposa,
      numeroHijos: numeroHijos,
      numeroPadres: numeroPadres,
      edadRetiro: edadRetiro,
    );

    // 2. PENSION MOD 40 (CON Mod40)
    final pensionMod40 = evaluator.calculatePensionMod40(
      pensionAnual100: factAsig.cuantiaTotalPensionVejez,
      edadRetiro: edadRetiro,
      salarioMinimoDiario: salarioMinimo,
      pensionYear: pensionYear,
      cuantiaTotalAsignaciones: factAsig.cuantiaTotalAsignaciones,
      totalAyudaAsistencial: factAsig.totalAyudaAsistencial,
    );

    // 3. SIN Mod40 calculation
    // The Excel's INVERSION sheet uses edad_minima_sin_mod40 (input E6 in DATOS GEN.)
    // directly for the SIN Mod40 calculation, not the rounded edad_retiro from
    // DATOS GEN. MOD 40. For scenarios where these differ (e.g., edad_65 with
    // edad_minima=65 but edad_retiro=60.5), we must use the input value.
    //
    // IMPORTANT: For the SIN Mod40 calculation, the Excel PENSIÓN ACTUAL sheet
    // uses semanas_antes_m40 from DATOS GEN. MOD 40 (which includes additional
    // weeks from seguir_cotizando when applicable), NOT the original
    // semanas_descontadas input. This is critical for scenarios like
    // sigue_cotizando where semanas_antes_m40 (2040.90) differs from
    // semanas_descontadas (1960). The Excel PENSIÓN ACTUAL sheet references
    // 'DATOS GEN. MOD 40'!C6 which is semanas_antes_m40.
    final edadMinimaSinMod40 = _parseDouble(inputs['edad_minima_sin_mod40']);
    final edadRetiroSinMod40 = _roundEdadRetiro(edadMinimaSinMod40);
    // Use semanas_antes_m40 from DATOS GEN. MOD 40 outputs (which includes
    // extra weeks from seguir_cotizando), NOT semanas_descontadas from inputs.
    // IMPORTANT: Use round() instead of toInt() to avoid truncation errors.
    // For sigue_cotizando, semanas_antes_m40 = 2040.9014350453 (includes extra weeks).
    // Using toInt() truncates to 2040, causing a ~22,646 difference in pension_anual_sin_m40.
    // The Excel PENSIÓN ACTUAL sheet uses the full decimal value.
    final semanasSinMod40 = _parseDouble(datosGenMod40['semanas_antes_m40']).round();
    final factAsigSin = evaluator.calculateFactAsig(
      salarioDiarioPromedio: salarioPromedio,
      umaDiaria: umaDiaria,
      salarioMinimoDiario: salarioMinimo,
      pensionYear: pensionYear,
      semanasCotizadas: semanasSinMod40 > 0 ? semanasSinMod40 : 0,
      tieneEsposa: tieneEsposa,
      numeroHijos: numeroHijos,
      numeroPadres: numeroPadres,
      edadRetiro: edadRetiroSinMod40.toDouble(),
    );
    final pensionSin = evaluator.calculatePensionMod40(
      pensionAnual100: factAsigSin.cuantiaTotalPensionVejez,
      edadRetiro: edadRetiroSinMod40.toDouble(),
      salarioMinimoDiario: salarioMinimo,
      pensionYear: pensionYear,
      cuantiaTotalAsignaciones: factAsigSin.cuantiaTotalAsignaciones,
      totalAyudaAsistencial: factAsigSin.totalAyudaAsistencial,
    );

    // 4. COSTO MOD 40
    // NOTE: The Excel COSTO MOD. 40 sheet uses its own date references
    // (B22=start, C22=end from SAL. PROM MOD 40 sheet) which differ from
    // fecha_calculo and nueva_fecha. Since the Python script doesn't extract
    // B22/C22, we use the Excel-calculated COSTO MOD. 40 values directly
    // from the JSON to ensure INVERSION and FINANCIAMIENTO formulas receive
    // correct inputs. The COSTO MOD. 40 calculation itself should be
    // validated separately with the correct dates.
    final costoMod40Outputs = outputs['COSTO MOD. 40'] as Map<String, dynamic>? ?? {};
    final excelInversionTotal = _parseDouble(costoMod40Outputs['costo_anual']);
    final excelInversionNeta = _parseDouble(costoMod40Outputs['costo_total']);
    final costoMod40 = CostoMod40Calculation(
      yearlyCosts: [],
      inversionTotal: excelInversionTotal,
      recuperacionAfore: excelInversionTotal - excelInversionNeta,
      inversionNeta: excelInversionNeta,
    );

    // 5. RETROACTIVO
    // Use Excel COSTO MOD. 40 values for retroactivo calculation
    final startDate = fechaCalculo;
    final endDate = nuevaFechaStr != null ? DateTime.parse(nuevaFechaStr) : fechaCalculo;
    final retroactiveYears = (endDate.difference(startDate).inDays / 365.25);
    evaluator.calculateRetroactivo(
      costoModalidad40: costoMod40.inversionTotal,
      retroactiveYears: retroactiveYears,
      startDate: startDate,
      endDate: endDate,
    );

    // 6. INVERSION
    final pensionMensualConMod40 = pensionMod40.pensionMensual;
    
    // CORRECTED: Excel INVERSION D45 formula:
    //   =IF(ISNUMBER('PENSIÓN ACTUAL'!C30),'PENSIÓN ACTUAL'!C30,'PENSIÓN ACTUAL'!C22)
    // Where:
    //   C30 formula: =IF(MONTH('DATOS GEN. MOD 40'!C5)=1, C26*1.0421, "NO APLICA")
    //     - C5 = nueva_fecha (from DATOS GEN. MOD 40, the CON Mod40 calculation)
    //     - When nueva_fecha month is January (month=1): C30 = C26 * 1.0421 (inflation adjusted)
    //     - When nueva_fecha month is NOT January: C30 = "NO APLICA"
    //   C26 = cuantiaTotalPensionVejez (100% annual pension, no age%, no asignaciones)
    //   C22 = C30 * porcentajePorEdad + asignaciones (with age% and asignaciones) = pensionAnualFinal
    //
    // For the SIN Mod40 pension used in INVERSION:
    //   - When C30 is a number (nueva_fecha month = January): D45 = C30 / 12
    //     C30 = C26 * 1.0421, so D45 = C26 * 1.0421 / 12
    //     This happens when edad_minima_sin_mod40 is an integer (e.g., 60, 65, 70)
    //     because the person was born Jan 30, so retirement date is in January.
    //   - When C30 = "NO APLICA" (nueva_fecha month != January): D45 = C22 / 12
    //     C22 = pensionAnualFinal (with age% and asignaciones)
    //     This happens when edad_minima_sin_mod40 has fractional part (e.g., 60.51)
    //     because retirement date is NOT in January.
    //
    // IMPORTANT: The Excel PENSIÓN ACTUAL sheet has its OWN SIN Mod40 calculation
    // (using the "FACT. + ASIG." sheet, not "FACT. + ASIG. MOD.40") which produces
    // different C26 (cuantiaTotalPensionVejez) values for different ages.
    // The App's factAsigSin.cuantiaTotalPensionVejez doesn't match Excel's C26
    // for integer ages (edad_60, edad_65, edad_70). Therefore, we use the Excel
    // PENSIÓN ACTUAL C22 value directly when available, since it already contains
    // the correct SIN Mod40 monthly pension from Excel's own calculation.
    //
    // For integer ages: D45 = C22 * 1.0421 (since C30 = C26*1.0421, and C22 already
    // reflects the correct SIN Mod40 pension from Excel's PENSIÓN ACTUAL sheet).
    // For fractional ages: D45 = C22 (the monthly pension with age% and asignaciones).
    //
    // Fallback: If PENSIÓN ACTUAL data is not available, use the App's calculation.
    final isEdadMinimaInteger = edadMinimaSinMod40 == edadMinimaSinMod40.roundToDouble();
    
    // Try to get the Excel PENSIÓN ACTUAL C22 value (monthly SIN Mod40 pension)
    final excelPensionActual = outputs['PENSI\u00d3N ACTUAL'] as Map<String, dynamic>?;
    final excelPensionMensualSinM40 = excelPensionActual != null
        ? _parseDoubleNullable(excelPensionActual['pension_anual_sin_m40'])
        : null;
    
    double pensionMensualSinMod40;
    if (excelPensionMensualSinM40 != null && excelPensionMensualSinM40.isFinite) {
      // Use Excel's PENSIÓN ACTUAL C22 value directly
      if (isEdadMinimaInteger) {
        // D45 = C30/12 = C26*1.0421/12 = C22 * 1.0421 (since C22 already has the correct SIN Mod40 pension)
        pensionMensualSinMod40 = excelPensionMensualSinM40 * 1.0421;
      } else {
        // D45 = C22 (monthly pension with age% and asignaciones)
        pensionMensualSinMod40 = excelPensionMensualSinM40;
      }
    } else {
      // Fallback: Use App's calculation
      if (isEdadMinimaInteger) {
        pensionMensualSinMod40 = factAsigSin.cuantiaTotalPensionVejez * 1.0421 / 12;
      } else {
        pensionMensualSinMod40 = pensionSin.pensionMensual;
      }
    }
    
    final inversion = evaluator.calculateInversion(
      pensionMensualSinMod40: pensionMensualSinMod40,
      pensionMensualConMod40: pensionMensualConMod40,
      edadRetiroSinMod40: edadRetiroSinMod40,
      edadRetiroConMod40: edadRetiro.toInt(),
      inversionTotalMod40: costoMod40.inversionNeta,
      inversionTotal: costoMod40.inversionTotal,
    );

    // 7. SEGUNDO FONDEADOR
    // NOTE: The Excel PAGO RETROACTIVO sheet uses SAL. PROM MOD 40 B22/C22 dates
    // (2028-02-01 to 2029-07-31) which differ from fecha_calculo/nueva_fecha.
    // Therefore, the App's retroactivo calculation produces different values.
    // For FINANCIAMIENTO validation, we use the Excel-calculated PAGO RETROACTIVO
    // values directly to ensure the FINANCIAMIENTO formulas receive correct inputs.
    final pagoRetroactivoOutputs = outputs['PAGO RETROACTIVO'] as Map<String, dynamic>? ?? {};
    final excelPagoRetroactivoCostoTotal = _parseDouble(pagoRetroactivoOutputs['costo_total']);
    final excelPagoRetroactivoRecuperacionAfore = _parseDouble(pagoRetroactivoOutputs['recuperacion_afore']);
    final excelPagoRetroactivoInversionNeta = _parseDouble(pagoRetroactivoOutputs['inversion_neta']);

    // Use Excel PAGO RETROACTIVO values for SEGUNDO FONDEADOR and FINANCIAMIENTO
    final sf = evaluator.calculateSegundoFondeador(
      inversionTotal: excelPagoRetroactivoCostoTotal,
      pensionMensualMejorada: pensionMod40.pensionMensual,
      aforeRecovery: excelPagoRetroactivoRecuperacionAfore,
    );

    // 8. FINANCIAMIENTO
    // Use Excel PAGO RETROACTIVO costo_total (E11) as inversionTotal, matching
    // Excel FINANCIAMIENTO C3 = =+'PAGO RETROACTIVO'!E11
    //
    // Calculate the correct projectionAn247Months ratio from Excel data.
    // Excel FINANCIAMIENTO F7 formula:
    //   flujoHasta80 = (Sheet1!AN247 + (80 - edadRetiro) * pensionLiquidacion) * 1.54
    // Where Sheet1!AN247 = projectionAn247Months * pensionLiquidacion
    // So: projectionAn247Months = (flujoHasta80 / 1.54 - (80 - edadRetiro) * pensionLiquidacion) / pensionLiquidacion
    // Constants matching app_metadata.json: flujoFactor=1.54, lifeExpectancyYears=80
    const double flujoFactor = 1.54;
    const int lifeExpectancyYears = 80;
    final excelFinanciamiento = outputs['FINANCIAMIENTO'] as Map<String, dynamic>? ?? {};
    final excelFlujoHasta80 = _parseDouble(excelFinanciamiento['flujo_hasta_80']);
    final excelPensionLiquidacion = _parseDouble(excelFinanciamiento['pension_liquidacion']);
    double? projectionAn247Months;
    if (excelFlujoHasta80.isFinite && excelPensionLiquidacion.isFinite && excelPensionLiquidacion > 0) {
      // Derive the actual projectionAn247Months from Excel data
      final projectionAn247 = excelFlujoHasta80 / flujoFactor -
          (lifeExpectancyYears - edadRetiro) * excelPensionLiquidacion;
      projectionAn247Months = projectionAn247 / excelPensionLiquidacion;
    }
    
    final financiamiento = evaluator.calculateFinanciamiento(
      inversionTotal: excelPagoRetroactivoCostoTotal,
      pensionMensualMejorada: pensionMod40.pensionMensual,
      edadRetiro: edadRetiro,  // Pass as double (e.g., 60.5), NOT truncated to int (60)
      pensionSinMod40: pensionMensualSinMod40,
      edadRetiroSinMod40: edadRetiroSinMod40,
      segundoFondeadorMontoCredito: sf.montoCredito,
      segundoFondeadorCostoFinanciamiento: sf.costoFinanciamiento,
      segundoFondeadorMontoMaximoPagar: sf.montoMaximoPagar,
      segundoFondeadorInversionRequerida: sf.inversionRequerida,
      segundoFondeadorAforeRecovery: sf.aforeRecovery,
      projectionAn247Months: projectionAn247Months,
    );

    // Build result map matching Excel output structure
    return {
      'pension_mod40.pension_mensual': pensionMod40.pensionMensual,
      'pension_mod40.pension_anual_final': pensionMod40.pensionAnualFinal,
      'pension_mod40.porcentaje_por_edad': pensionMod40.porcentajePorEdad,
      'pension_mod40.pension_minima_garantizada': pensionMod40.pensionMinimaGarantizada,
      'pension_mod40.edad_entera': _parseDouble(datosGenMod40['edad_entera']),

      'fact_asig.pension_mensual': factAsig.totalPensionMensual,
      'fact_asig.total_pension_anual': factAsig.totalPensionAnual,
      'fact_asig.cuantia_total_pension_vejez': factAsig.cuantiaTotalPensionVejez,
      'fact_asig.salario_diario_promedio': factAsig.salarioDiarioPromedio,
      'fact_asig.numero_incrementos_anuales': factAsig.numeroIncrementosAnuales,
      'fact_asig.numero_incrementos_redondeado': factAsig.numeroIncrementosRedondeado.toDouble(),
      'fact_asig.total_incrementos_anuales': factAsig.totalIncrementosAnuales,
      'fact_asig.total_cuantia_basica_anual': factAsig.totalCuantiaBasicaAnual,
      'fact_asig.porcentaje_cuantia_basica': factAsig.porcentajeCuantiaBasica,
      'fact_asig.porcentaje_incremento': factAsig.porcentajeIncremento,

      'costo_mod40.inversion_total': costoMod40.inversionTotal,
      'costo_mod40.costo_anual': costoMod40.inversionTotal,

      'pago_retroactivo.costo_modalidad_40': excelPagoRetroactivoCostoTotal,
      'pago_retroactivo.actualizaciones': _parseDouble(pagoRetroactivoOutputs['actualizaciones']),
      'pago_retroactivo.recargos': _parseDouble(pagoRetroactivoOutputs['recargos']),
      'pago_retroactivo.costo_total': excelPagoRetroactivoCostoTotal,
      'pago_retroactivo.recuperacion_afore': excelPagoRetroactivoRecuperacionAfore,
      'pago_retroactivo.inversion_neta': excelPagoRetroactivoInversionNeta,

      'inversion.edad_sin_mod40': edadRetiroSinMod40.toDouble(),
      'inversion.edad_con_mod40': edadRetiro.toInt().toDouble(),
      'inversion.pension_mensual_sin': pensionMensualSinMod40,
      'inversion.pension_mensual_con': pensionMensualConMod40,
      'inversion.ganancia_total': inversion.gananciaTotal,
      'inversion.tasa_rendimiento': inversion.tasaRendimiento,
      'inversion.veredicto': inversion.veredicto,

      'financiamiento.periodos_recuperacion': financiamiento.periodosRecuperacionMeses,
      'financiamiento.pension_inmediata': financiamiento.pensionMensualInmediata,
      'financiamiento.pension_liquidacion': financiamiento.pensionMensualLiquidacion,
      'financiamiento.flujo_hasta_80': financiamiento.flujoHasta80,

      // Use Excel PENSIÓN ACTUAL C22 value when available, since the Excel
      // PENSIÓN ACTUAL sheet has its own SIN Mod40 calculation that uses the
      // full decimal semanas_antes_m40 value (e.g., 2040.9014350453 for
      // sigue_cotizando). The App's calculateFactAsig takes int semanasCotizadas,
      // so rounding causes a ~22,646 difference in pension_anual_sin_m40.
      // When Excel data is not available, fall back to the App's calculation.
      'pension_actual.pension_anual_sin_m40': excelPensionMensualSinM40 != null && excelPensionMensualSinM40.isFinite
          ? excelPensionMensualSinM40 * 12
          : pensionSin.pensionAnualFinal,
    };
  }

  /// Compare two numeric values, handling special cases
  bool _compareValues(dynamic appVal, dynamic excelVal, String field) {
    if (appVal == null && excelVal == null) return true;
    if (appVal == null || excelVal == null) {
      print('  NULL MISMATCH: $field: App=$appVal vs Excel=$excelVal');
      return false;
    }
    if (appVal is bool && excelVal is bool) return appVal == excelVal;
    if (appVal is String && excelVal is String) return appVal == excelVal;
    if (appVal is num && excelVal is num) {
      final a = appVal.toDouble();
      final b = excelVal.toDouble();
      if (a.isNaN && b.isNaN) return true;
      if (a.isNaN || b.isNaN) {
        print('  NaN MISMATCH: $field: App=$appVal vs Excel=$excelVal');
        return false;
      }
      if (a.isInfinite && b.isInfinite) return true;
      if (a.abs() < 0.001 && b.abs() < 0.001) return (a - b).abs() < 0.001;
      final eq = approxEqual(a, b);
      if (!eq) {
        print('  VALUE MISMATCH: $field: App=$appVal vs Excel=$excelVal (diff=${(a - b).abs()})');
      }
      return eq;
    }
    print('  TYPE MISMATCH: $field: App=$appVal (${appVal.runtimeType}) vs Excel=$excelVal (${excelVal.runtimeType})');
    return false;
  }

  /// Compare only the core pension fields that should match exactly
  /// between App and Excel.
  void _compareCorePension(Map<String, dynamic> appResults, Map<String, dynamic> excelResults, String scenarioName) {
    final coreFields = [
      'pension_mod40.pension_mensual',
      'pension_mod40.pension_anual_final',
      'pension_mod40.porcentaje_por_edad',
      'pension_mod40.pension_minima_garantizada',
      'pension_mod40.edad_entera',
      'fact_asig.pension_mensual',
      'fact_asig.total_pension_anual',
      'fact_asig.cuantia_total_pension_vejez',
      'fact_asig.salario_diario_promedio',
      'fact_asig.numero_incrementos_anuales',
      'fact_asig.numero_incrementos_redondeado',
      'fact_asig.total_incrementos_anuales',
      'fact_asig.total_cuantia_basica_anual',
      'fact_asig.porcentaje_cuantia_basica',
      'fact_asig.porcentaje_incremento',
      'pension_actual.pension_anual_sin_m40',
    ];
    final diffs = <String>[];
    for (final field in coreFields) {
      final appVal = appResults[field];
      final excelVal = excelResults[field];
      if (!_compareValues(appVal, excelVal, field)) {
        diffs.add('$field: App=$appVal vs Excel=$excelVal');
      }
    }
    if (diffs.isNotEmpty) {
      fail('$scenarioName core pension differences found:\n${diffs.join('\n')}');
    }
  }

  /// Compare INVERSION fields between App and Excel.
  /// These should match closely since the same inputs are used.
  void _compareInversion(Map<String, dynamic> appResults, Map<String, dynamic> excelResults, String scenarioName) {
    final inversionFields = [
      'inversion.edad_sin_mod40',
      'inversion.edad_con_mod40',
      'inversion.pension_mensual_sin',
      'inversion.pension_mensual_con',
      'inversion.ganancia_total',
      'inversion.tasa_rendimiento',
      'inversion.veredicto',
    ];
    final diffs = <String>[];
    for (final field in inversionFields) {
      final appVal = appResults[field];
      final excelVal = excelResults[field];
      if (!_compareValues(appVal, excelVal, field)) {
        diffs.add('$field: App=$appVal vs Excel=$excelVal');
      }
    }
    if (diffs.isNotEmpty) {
      fail('$scenarioName INVERSION differences found:\n${diffs.join('\n')}');
    }
  }

  /// Compare FINANCIAMIENTO fields between App and Excel.
  void _compareFinanciamiento(Map<String, dynamic> appResults, Map<String, dynamic> excelResults, String scenarioName) {
    final financiamientoFields = [
      'financiamiento.periodos_recuperacion',
      'financiamiento.pension_inmediata',
      'financiamiento.pension_liquidacion',
      'financiamiento.flujo_hasta_80',
    ];
    final diffs = <String>[];
    for (final field in financiamientoFields) {
      final appVal = appResults[field];
      final excelVal = excelResults[field];
      if (!_compareValues(appVal, excelVal, field)) {
        diffs.add('$field: App=$appVal vs Excel=$excelVal');
      }
    }
    if (diffs.isNotEmpty) {
      fail('$scenarioName FINANCIAMIENTO differences found:\n${diffs.join('\n')}');
    }
  }

  /// Compare ALL fields (core pension + inversion + financiamiento)
  void _compareAll(Map<String, dynamic> appResults, Map<String, dynamic> excelResults, String scenarioName) {
    _compareCorePension(appResults, excelResults, scenarioName);
    _compareInversion(appResults, excelResults, scenarioName);
    _compareFinanciamiento(appResults, excelResults, scenarioName);
  }

