      final baseUserPension = baseUserResults['pension_mod40.pension_mensual'] as double;
      // NOTE: Both can be equal when numeroIncrementosRedondeado rounds to the same value
      // (e.g., 29.58 and 28.08 both round to 30 with Art. 167 rules).
      // In that case, the pension is identical despite different semanas.
      expect(baselinePension, greaterThanOrEqualTo(baseUserPension),
          reason: 'Baseline (more semanas) should have >= pension than base_user');
